package store

import (
	"context"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/justindeelux/gotham/internal/store/sqlc"
)

// Store aggregates the persistence repositories. It owns the connection pool
// and exposes the typed queries generated by sqlc. Phase 1 replaces the flat
// user methods with dedicated repositories as the auth schema grows.
type Store struct {
	DB      *pgxpool.Pool
	queries *sqlc.Queries
}

// New wires a Store to an existing pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{
		DB:      pool,
		queries: sqlc.New(pool),
	}
}

// GetUserByEmail returns the user with the given email. The lookup is
// case-insensitive, backed by the users_email_lower_idx functional index.
func (s *Store) GetUserByEmail(ctx context.Context, email string) (sqlc.User, error) {
	return s.queries.GetUserByEmail(ctx, email)
}

// GetUserByID returns the user with the given ID.
func (s *Store) GetUserByID(ctx context.Context, id pgtype.UUID) (sqlc.User, error) {
	return s.queries.GetUserByID(ctx, id)
}

// CreateUser inserts a user with the given email and password hash (nil when
// the account has no local password) and returns the stored row.
func (s *Store) CreateUser(ctx context.Context, email string, passwordHash *string) (sqlc.User, error) {
	return s.queries.CreateUser(ctx, sqlc.CreateUserParams{
		Email:        email,
		PasswordHash: passwordHash,
	})
}

// CreateSession stores a refresh-token session and returns the stored row.
func (s *Store) CreateSession(ctx context.Context, params sqlc.CreateSessionParams) (sqlc.Session, error) {
	return s.queries.CreateSession(ctx, params)
}

// GetSessionByRefreshHash returns the session with the given refresh-token hash.
func (s *Store) GetSessionByRefreshHash(ctx context.Context, refreshHash string) (sqlc.Session, error) {
	return s.queries.GetSessionByRefreshHash(ctx, refreshHash)
}

// RevokeSession marks the session with the given refresh-token hash as revoked.
// It is idempotent: an unknown or already-revoked token is not an error.
func (s *Store) RevokeSession(ctx context.Context, refreshHash string) error {
	return s.queries.RevokeSession(ctx, refreshHash)
}

// CreateAPIToken stores a scoped API token (hash only) and returns the row.
func (s *Store) CreateAPIToken(ctx context.Context, params sqlc.CreateAPITokenParams) (sqlc.ApiToken, error) {
	return s.queries.CreateAPIToken(ctx, params)
}

// ListAPITokensByUser returns every API token owned by userID, newest first,
// including revoked tokens so the caller can display their state.
func (s *Store) ListAPITokensByUser(ctx context.Context, userID pgtype.UUID) ([]sqlc.ApiToken, error) {
	return s.queries.ListAPITokensByUser(ctx, userID)
}

// GetAPITokenByHash returns the API token with the given hash.
func (s *Store) GetAPITokenByHash(ctx context.Context, hash string) (sqlc.ApiToken, error) {
	return s.queries.GetAPITokenByHash(ctx, hash)
}

// GetAPITokenByIDAndUser returns the API token with the given ID when it is
// owned by userID.
func (s *Store) GetAPITokenByIDAndUser(ctx context.Context, params sqlc.GetAPITokenByIDAndUserParams) (sqlc.ApiToken, error) {
	return s.queries.GetAPITokenByIDAndUser(ctx, params)
}

// RevokeAPIToken marks an owned, active token as revoked and reports how many
// rows were affected (0 when the token is unknown, not owned, or already
// revoked).
func (s *Store) RevokeAPIToken(ctx context.Context, params sqlc.RevokeAPITokenParams) (int64, error) {
	return s.queries.RevokeAPIToken(ctx, params)
}

// TouchAPITokenLastUsed records when the token was last presented.
func (s *Store) TouchAPITokenLastUsed(ctx context.Context, params sqlc.TouchAPITokenLastUsedParams) error {
	return s.queries.TouchAPITokenLastUsed(ctx, params)
}
